<script lang="ts">
  // Turning archive encryption on: choose a password, then prove you have the
  // recovery key.
  //
  // The order is the whole point. The recovery key is generated by the service,
  // shown once and stored nowhere — so if the job were saved BEFORE it had been
  // written down, one forgotten password would make every copy unreadable with
  // nothing left to say so. Step 2 therefore writes nothing; the authorization
  // is committed only when the key comes back typed correctly.
  //
  // Typing it back is not ceremony: the key carries a checksum, so a mistyped
  // one is named as mistyped rather than quietly accepted — and a dialog
  // clicked through without reading cannot pass.
  import Modal from './Modal.svelte';
  import PasswordField from './PasswordField.svelte';
  import { api } from '../lib/api';
  import { enableArchiveEncryption } from '../lib/jobStore.svelte';
  import type { BegunArchiveEncryption, Job } from '../lib/types';

  interface Props {
    open: boolean;
    /** The job as the wizard has it — saved by the service as part of the
     *  same transaction that stores the key. */
    job: Job;
    /** The stored job, once encryption is on. */
    onDone: (saved: Job) => void;
    onCancel: () => void;
  }

  let { open, job, onDone, onCancel }: Props = $props();

  type Step = 'password' | 'recovery';
  let step = $state<Step>('password');
  let password = $state('');
  let again = $state('');
  let begun = $state<BegunArchiveEncryption | null>(null);
  let echo = $state('');
  let busy = $state(false);
  let error = $state('');

  const MIN_PASSWORD = 8;
  const passwordsMatch = $derived(password.length > 0 && password === again);
  const passwordReady = $derived(passwordsMatch && password.length >= MIN_PASSWORD);

  async function prepare() {
    if (!passwordReady || busy) return;
    busy = true;
    error = '';
    try {
      begun = await api.beginArchiveEncryption(job, password);
      step = 'recovery';
    } catch (e) {
      error = String(e);
    } finally {
      busy = false;
    }
  }

  async function commit() {
    if (!begun || echo.trim().length === 0 || busy) return;
    busy = true;
    error = '';
    try {
      // Through the store, so the job list shows the job the moment it exists
      // — for a new job this commit IS its creation.
      const saved = await enableArchiveEncryption(begun.token, echo);
      reset();
      onDone(saved);
    } catch (e) {
      // The service keeps the request alive for a survivable typo and says how
      // many tries are left; when they run out it is gone and the message says
      // so. Either way the text it sends is the one to show.
      error = String(e);
    } finally {
      busy = false;
    }
  }

  function reset() {
    step = 'password';
    password = '';
    again = '';
    echo = '';
    begun = null;
    error = '';
  }

  async function cancel() {
    // Nothing was written, but the service is holding a prepared key in memory
    // — say it is no longer wanted rather than leaving it to time out.
    if (begun) {
      try {
        await api.cancelArchiveEncryption(begun.token);
      } catch {
        // It expires by itself; a failure here changes nothing.
      }
    }
    reset();
    onCancel();
  }

  async function copyKey() {
    if (!begun) return;
    try {
      await navigator.clipboard.writeText(begun.recovery_key);
    } catch {
      // No clipboard (a boot medium may have none) — the key is on screen.
    }
  }
</script>

<Modal
  open={open}
  title={step === 'password' ? 'Шифрование копий' : 'Ключ восстановления'}
  onClose={cancel}
  onConfirm={step === 'password'
    ? passwordReady && !busy
      ? prepare
      : undefined
    : echo.trim().length > 0 && !busy
      ? commit
      : undefined}
  confirmLabel={step === 'password'
    ? busy
      ? 'Готовлю ключ…'
      : 'Далее'
    : busy
      ? 'Включаю…'
      : 'Включить шифрование'}
  cancelLabel="Отмена"
>
  {#if step === 'password'}
    <p class="what">
      Копии этого задания будут шифроваться. Прочитать их можно будет только этим
      паролем или ключом восстановления — <b>ни служба, ни мы не сможем открыть
      их иначе</b>.
    </p>

    <div class="field-label">Пароль архива:</div>
    <PasswordField value={password} oninput={(v) => (password = v)} placeholder="Пароль архива" />
    <div class="field-label mt">Ещё раз:</div>
    <PasswordField
      value={again}
      oninput={(v) => (again = v)}
      onenter={prepare}
      placeholder="Повторите пароль"
      invalid={again.length > 0 && !passwordsMatch}
    />

    {#if password.length > 0 && password.length < MIN_PASSWORD}
      <p class="note warn">Не короче {MIN_PASSWORD} символов.</p>
    {:else if again.length > 0 && !passwordsMatch}
      <p class="note warn">Пароли не совпадают.</p>
    {/if}

    <p class="note">
      Формат образов станет .obk — наш контейнер с шифрованием. Уже снятые копии
      остаются как есть; шифроваться будут следующие.
    </p>
    {#if busy}
      <p class="note">
        Подготовка ключа занимает несколько секунд — так и задумано.
      </p>
    {/if}
  {:else if begun}
    <p class="what">
      Запишите ключ восстановления <b>сейчас</b>. Он показывается один раз и
      нигде не сохраняется.
    </p>

    <div class="key-box">
      <code>{begun.recovery_key}</code>
      <button class="copy" onclick={copyKey} title="Скопировать в буфер обмена">
        Скопировать
      </button>
    </div>

    <p class="note">
      Отпечаток ключа задания: <code class="fp">{begun.fingerprint.slice(0, 16)}…</code>
    </p>

    <div class="field-label mt">Введите ключ восстановления, чтобы подтвердить:</div>
    <PasswordField
      value={echo}
      oninput={(v) => (echo = v)}
      onenter={commit}
      placeholder="obk1…"
      invalid={!!error}
      revealed={true}
    />
    <p class="note">
      Пока он не введён, ничего не сохранено: задание останется без шифрования.
    </p>
  {/if}

  {#if error}
    <p class="err">{error}</p>
  {/if}
</Modal>

