    margin: 0 0 14px;
    font-size: 13px;
    line-height: 1.5;
    color: var(--text);
  }
  .field-label {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 5px;
  }
  .field-label.mt {
    margin-top: 12px;
  }
  .note {
    margin: 8px 0 0;
    font-size: 12px;
    color: var(--text-muted);
    line-height: 1.45;
  }
  .note.warn {
    color: #d08a2a;
  }
  .key-box {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px;
    margin: 4px 0 2px;
    border: 1px solid var(--primary);
    border-radius: 6px;
    background: var(--card-bg);
  }
  .key-box code {
    flex: 1 1 auto;
    font-family: ui-monospace, 'Cascadia Mono', 'Consolas', monospace;
    font-size: 13px;
    line-height: 1.6;
    word-break: break-all;
    color: var(--text);
    user-select: all;
  }
  .copy {
    flex: 0 0 auto;
    padding: 6px 10px;
    font-size: 12px;
    border: 1px solid var(--border);
    border-radius: 5px;
    background: transparent;
    color: var(--text-muted);
    cursor: pointer;
  }
  .copy:hover {
    color: var(--text);
  }
  .fp {
    font-family: ui-monospace, 'Cascadia Mono', 'Consolas', monospace;
    font-size: 11px;
  }
  .err {
    margin: 10px 0 0;
    padding: 8px 10px;
    font-size: 12px;
    border-radius: 5px;
    background: rgba(216, 74, 74, 0.12);
    color: #d84a4a;
  }
</style>
